import React, { useEffect, useState } from 'react';
import { Box, Typography, Stack } from '@mui/material';
import { EmojiObjects, CalendarToday, Person } from '@mui/icons-material';
import MinimalAppBar from '../../Component/MinimalAppBar';
import { useLocation } from 'react-router-dom';

const DetailRow: React.FC<any> = ({ label, value, icon }) => (
    <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        py={1}
        borderBottom="1px solid #eee"
    >
        <Box display="flex" alignItems="center" gap={1}>
            {icon}
            <Typography fontWeight="bold">{label}</Typography>
        </Box>
        <Typography>{value}</Typography>
    </Box>
);

const LoanDetail: React.FC = () => {
    
const location = useLocation();
  const loanData = location.state;
 const [data,setData] = useState<any>(loanData);
    return (<>
        <MinimalAppBar onBack={() => window.history.back} title="สินเชื่อของฉัน"></MinimalAppBar>
        <Box p={2}>
            <Stack spacing={2}>
                <DetailRow label="สินค้า" value={data.productName} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="ยอดกู้" value={`฿${data.loanAmount.toLocaleString()}`} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="ดอกเบี้ย" value={`${data.interestRate}%`} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="ยอดผ่อน/เดือน" value={`฿${data.installmentAmount.toLocaleString()}`} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="เริ่มต้น" value={data.startDate} icon={<CalendarToday fontSize="small" />} />
                <DetailRow label="สิ้นสุด" value={data.endDate} icon={<CalendarToday fontSize="small" />} />
                <DetailRow label="ผู้กู้" value={data.memberName} icon={<Person fontSize="small" />} />
            </Stack>
        </Box>
    </>
    );
};

export default LoanDetail;
